            let rest = rest.skip(n1);
            let (n2, ticket_age_add) = (U32Be).parse (& rest) ?;
            let rest = rest.skip(n2);
            let (n3, ticket_nonce) = (Named ("opaque_0_ff", Opaque0FfFmt)).parse (& rest) ?;
            let rest = rest.skip(n3);
